    public bool handle_event(RefCounted owner,InputEvent input)
    {
        if(!available(owner))return false;var actor=Actor(Runtime(owner)!);var gizmo=Gizmo(owner);var spatial=Spatial(owner);var model=Model(owner);if(input is InputEventKey toggle&&toggle.Pressed&&!toggle.Echo&&toggle.Keycode==Key.D&&gizmo.HasFocus()){actor.SetMeta("damage_viewport_tool",!active(owner));gizmo.QueueRedraw();return true;}if(input is InputEventMouseButton tool&&tool.ButtonIndex==MouseButton.Left&&tool.Pressed&&spatial.Call("toolbar_rect",3).AsRect2().HasPoint(tool.Position)){actor.SetMeta("damage_viewport_tool",!active(owner));gizmo.GrabFocus();return true;}if(!active(owner))return false;if(actor.GetMeta("damage_fragment_tool",false).AsBool())return fragment_event(owner,input,actor);if(input is InputEventKey escape&&escape.Pressed&&escape.Keycode==Key.Escape){if(Before(owner).Count>0){restore(owner,Before(owner),owner.Get("tracks").AsGodotArray());owner.Set("before",new Settings());}actor.SetMeta("damage_viewport_tool",false);return true;}var operation=selected_operation(owner);if(operation.Count==0)return false;var pose=Runtime(owner)!.Call("remote_transform").AsTransform3D();var point=pose*Get(operation,"position",Vector3.Zero).AsVector3();
        if(actor.GetMeta("damage_path_tool",false).AsBool()&&input is InputEventMouseButton pathClick&&pathClick.Pressed){if(pathClick.ButtonIndex==MouseButton.Right){actor.SetMeta("damage_path_tool",false);return true;}if(pathClick.ButtonIndex==MouseButton.Left){var ray=spatial.Call("_ray",pathClick.Position).AsGodotDictionary();Variant hit=default;foreach(var visual in spatial.Call("visuals",Runtime(owner)!).AsGodotArray()){var candidate=spatial.Call("_hit_visual",visual,ray);if(candidate.VariantType!=Variant.Type.Nil&&(hit.VariantType==Variant.Type.Nil||ray["origin"].AsVector3().DistanceSquaredTo(candidate.AsVector3())<ray["origin"].AsVector3().DistanceSquaredTo(hit.AsVector3())))hit=candidate;}if(hit.VariantType!=Variant.Type.Nil){var operations=Operations(actor).Duplicate(true);string id=Selected(actor,operations);var selected=operations[id].AsGodotDictionary();var path=Get(selected,"path",Array.Empty<Vector3>()).AsVector3Array();if(path.Length<33){selected["path"]=path.Append(pose.AffineInverse()*hit.AsVector3()).ToArray();selected["direction"]=pose.Basis.Inverse()*Camera(owner).GlobalBasis.Z;_definition.edit(model,actor,operations,"Place fracture path point");}}return true;}}
        if(input is InputEventMouseButton wheel&&wheel.ShiftPressed&&wheel.Pressed&&(wheel.ButtonIndex is MouseButton.WheelUp or MouseButton.WheelDown)){var operations=Operations(actor).Duplicate(true);string id=Selected(actor,operations);double radius=Math.Max(.001,Get(operation,"radius",.5).AsDouble()*(wheel.ButtonIndex==MouseButton.WheelUp?1.1:1/1.1));var path=new[]{"destruction_operations",id,"radius"};if(_data.animation_track(actor,path)!=null)model.Call("commit_animation_value",actor,path,radius);else{operations[id].AsGodotDictionary()["radius"]=radius;_definition.edit(model,actor,operations,"Damage radius");}return true;}
        if(input is InputEventMouseButton click&&click.ButtonIndex==MouseButton.Left){if(click.Pressed){if(Project(owner,point).DistanceTo(click.Position)>12)return false;owner.Set("actor",actor);var before=_data.copy_value(Operations(actor)).AsGodotDictionary();owner.Set("before",before);owner.Set("tracks",model.Call("animation_snapshot",actor));owner.Set("selected",Selected(actor,before));owner.Set("plane",new Plane(Camera(owner).GlobalBasis.Z,point));var hit=PlaneHit(owner,spatial.Call("_ray",click.Position).AsGodotDictionary());owner.Set("offset",hit.HasValue?point-hit.Value:Vector3.Zero);gizmo.GrabFocus();return true;}if(Before(owner).Count>0){var target=owner.Get("actor").As<Resource>();var after=_data.copy_value(Operations(target)).AsGodotDictionary();var afterTracks=model.Call("animation_snapshot",target).AsGodotArray();string selected=owner.Get("selected").AsString();var path=new[]{"destruction_operations",selected,"position"};if(_data.animation_track(target,path)!=null){var value=_animation.sampled_value(target,path,target.Get("animation_time").AsDouble(),after[selected].AsGodotDictionary()["position"]);restore(owner,Before(owner),owner.Get("tracks").AsGodotArray());model.Call("commit_animation_value",target,path,value);}else{var history=model.Get("history").As<UndoRedo>();var action=new DestructionOperationsHistoryAction(model,target,Before(owner),owner.Get("tracks").AsGodotArray(),after,afterTracks);history.CreateAction("Move damage operation");history.AddDoMethod(new Callable(action,nameof(DestructionOperationsHistoryAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(DestructionOperationsHistoryAction.restore_before)));history.AddDoReference(action);history.CommitAction();}owner.Set("before",new Settings());return true;}}
        if(input is InputEventMouseMotion motion&&Before(owner).Count>0){var hit=PlaneHit(owner,spatial.Call("_ray",motion.Position).AsGodotDictionary());if(hit.HasValue){var local=pose.AffineInverse()*(hit.Value+owner.Get("offset").AsVector3());if(motion.CtrlPressed)local=local.Snapped(Vector3.One*.1f);var target=owner.Get("actor").As<Resource>();string selected=owner.Get("selected").AsString();var path=new[]{"destruction_operations",selected,"position"};if(_data.animation_track(target,path)!=null)model.Call("preview_animation_value",target,path,local);else{var operations=Operations(target).Duplicate(true);operations[selected].AsGodotDictionary()["position"]=local;target.Get("values").AsGodotDictionary()[new StringName("destruction_operations")]=operations;model.EmitSignal("changed");}}return true;}return false;
    }
    public bool fragment_event(RefCounted owner,InputEvent input,Resource actor)
    {
        var model=Model(owner);var chosen=actor.GetMeta("damage_selected_fragments",new GArray()).AsGodotArray();var pieces=Pieces(owner,actor);var spatial=Spatial(owner);var gizmo=Gizmo(owner);if(input is InputEventKey escape&&escape.Pressed&&escape.Keycode==Key.Escape){owner.Set("fragment_drag",false);actor.SetMeta("damage_fragment_tool",false);actor.SetMeta("damage_viewport_tool",false);return true;}if(input is InputEventMouseButton click&&click.ButtonIndex==MouseButton.Left){if(click.Pressed){var rules=_data.get_value(actor,"destruction_fragments",new Settings()).AsGodotDictionary();foreach(var value in pieces){var fragment=value.AsGodotDictionary();string key=_authoring.fragment_key(actor.Get("id").AsString(),fragment["id"].AsString());if(!chosen.Contains(key))continue;var target=Get(Get(rules,key,new Settings()).AsGodotDictionary(),"target",fragment["pose"].AsTransform3D().Origin).AsVector3();if(Project(owner,target).DistanceTo(click.Position)<10){owner.Set("fragment_drag",true);owner.Set("fragment_origin",target);owner.Set("offset",target);owner.Set("plane",new Plane(Camera(owner).GlobalBasis.Z,target));gizmo.GrabFocus();return true;}}var nodes=Get(Physics(owner).Get("destruction").AsGodotObject().Get("nodes").AsGodotDictionary(),actor.Get("id").AsString(),new GArray()).AsGodotArray();float best=float.PositiveInfinity;string id="";var ray=spatial.Call("_ray",click.Position).AsGodotDictionary();for(int i=0;i<Math.Min(nodes.Count,pieces.Count);i++){var hit=spatial.Call("_hit_visual",nodes[i],ray);if(hit.VariantType==Variant.Type.Nil)continue;float distance=ray["origin"].AsVector3().DistanceSquaredTo(hit.AsVector3());if(distance<best){best=distance;id=_authoring.fragment_key(actor.Get("id").AsString(),pieces[i].AsGodotDictionary()["id"].AsString());}}if(!click.ShiftPressed)chosen=new GArray();if(id.Length>0&&!chosen.Contains(id))chosen.Add(id);actor.SetMeta("damage_selected_fragments",chosen);gizmo.GrabFocus();return true;}if(owner.Get("fragment_drag").AsBool()){owner.Set("fragment_drag",false);_authoring.edit_fragments(model,actor,new StringName("destruction_fragments"),chosen,"guided_target",owner.Get("offset"));return true;}}
        if(input is InputEventMouseMotion motion&&owner.Get("fragment_drag").AsBool()){var hit=PlaneHit(owner,spatial.Call("_ray",motion.Position).AsGodotDictionary());if(hit.HasValue)owner.Set("offset",motion.CtrlPressed?hit.Value.Snapped(Vector3.One*.1f):hit.Value);return true;}return false;
    }
